var a=[{title:`Po co łączyć jedno z drugim`,text:`Trening oporowy poprawia siłę i funkcję mięśni, a aktywność tlenowa wspiera wytrzymałość i zdrowie serca oraz płuc. Wytyczne zdrowia publicznego zalecają oba. Robienie tylko jednego może zostawić część Twojej sprawności w tyle, zwłaszcza gdy Twoje codzienne cele obejmują siłę, zdolność chodzenia i długotrwałą aktywność.`},{title:`Efekt interferencji`,text:`Bardzo duże ilości pracy wytrzymałościowej mogą czasem zmniejszać przyrosty mocy dynamicznej lub niektóre wyniki siłowe w porównaniu z samym treningiem oporowym. Najnowsze przeglądy wskazują jednak, że trening łączony zwykle poprawia razem wydolność tlenową i siłę, a większość osób trenujących rekreacyjnie nie traci przez to żadnego realnego przyrostu mięśni.`},{title:`Wybierz praktyczną kolejność`,text:`Jeśli priorytetem jest siła, wykonuj wymagające ćwiczenia, gdy jesteś świeży, a łatwe kardio potem. Jeśli głównym celem jest kondycja, najpierw wykonaj ważną pracę wytrzymałościową. Rozdzielenie ciężkich treningów o kilka godzin lub na różne dni może pomóc w zmęczeniu, zwłaszcza w treningu zaawansowanym.`},{title:`Zrównoważ ciężkie i łatwe dni`,text:`Na przykład wykonaj dwa dni siły całego ciała plus dwa lub trzy szybkie spacery i opcjonalny umiarkowany trening na rowerze. Bardziej doświadczony sportowiec może musieć starannie rozplanować ciężkie biegi i treningi siły nóg. Jeśli cierpią Twoje wyniki i regeneracja, przestań nakładać maksymalne interwały na każdy trening nóg.`},{title:`Korzystanie z TrainUp`,text:`Twój cel w Profilu (ogólna sprawność, siła lub kondycja) mówi, który rodzaj pracy postawić na pierwszym miejscu, gdy nadal trenujesz oba. Kardio nie psuje automatycznie postępów siłowych. Obserwuj opuszczone powtórzenia i średni wysiłek w Historii. Gdy ponownie generujesz plan, staje się łatwiejszy, jeśli 2 z Twoich ostatnich 3 treningów były bardzo ciężkie (RPE 9 lub więcej) albo ukończone w mniej niż 60%.`}];var n=[{label:`Przegląd przeglądów z 2026 roku: jednoczesny trening siłowy i wytrzymałościowy`,url:`https://pubmed.ncbi.nlm.nih.gov/41762427/`},{label:`CDC: zalecenia dotyczące aktywności fizycznej dorosłych`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var o={sections:a,sources:n};export{o as default,a as sections,n as sources};